async function availablePort(){const server=createServer();await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));const address=server.address();if(!address||typeof address==='string')throw new Error('No test port');const port=address.port;await new Promise<void>((resolve,reject)=>server.close(error=>error?reject(error):resolve()));return port;}
function sampleLocation(){
  const source=JSON.parse(readFileSync(join(process.cwd(),'geodata/sonla.full.geojson'),'utf8')) as BoundaryCollection;
  const feature=source.features.find(item=>item.properties.name.includes('Thảo Nguyên'));assert.ok(feature);
  const target={lng:104.704,lat:20.875};const targetCommune=resolveCommune(target);if(targetCommune?.code===feature.properties.communeCode)return{...target,communeCode:targetCommune.code};
  const [[west,south],[east,north]]=geometryBounds(feature.geometry);
  for(let x=1;x<10;x++)for(let y=1;y<10;y++){const position={lng:west+(east-west)*x/10,lat:south+(north-south)*y/10};const commune=resolveCommune(position);if(commune?.code===feature.properties.communeCode)return{...position,communeCode:commune.code};}
  throw new Error('Could not find test point in Thảo Nguyên.');
}
function chartLocations(count:number){
  const source=JSON.parse(readFileSync(join(process.cwd(),'geodata/sonla.full.geojson'),'utf8')) as BoundaryCollection;
  const result:{lat:number;lng:number;communeCode:string}[]=[];
  for(const feature of source.features){
    if(result.some(row=>row.communeCode===feature.properties.communeCode))continue;
    const [[west,south],[east,north]]=geometryBounds(feature.geometry);let found=false;
    for(let x=1;x<20&&!found;x++)for(let y=1;y<20&&!found;y++){
      const position={lng:west+(east-west)*x/20,lat:south+(north-south)*y/20};
      if(resolveCommune(position)?.code===feature.properties.communeCode){result.push({...position,communeCode:feature.properties.communeCode});found=true;}
    }
    if(result.length===count)return result;
  }
  throw new Error('Not enough valid chart fixture locations');
}
